-- BACKLOG-3473 MUTANT (generated by generate.mjs from the shipped files; do not hand-edit)
-- migration 2 creates checklist_templates without IF NOT EXISTS (second apply: 42P07)
-- replaces-file: 2
-- ============================================================================
-- Migration: transaction checklists -- org templates and the submitted copy
-- Backlog: BACKLOG-3473 (epic BACKLOG-2237)
--
-- NOT APPLIED TO PRODUCTION BY THIS PR. The apply is a separate step taken on
-- the founder's word. The admin plan editor renders every feature_definitions
-- row regardless of is_built, so applying this file makes a "Transaction
-- checklists" switch appear there.
--
-- Creates
-- ---------------------------------------------------------------------------
--   checklist_templates            an organization's templates
--   checklist_template_items       the items of a template
--   checklist_seed_templates       Keepr's starter catalogue (ships EMPTY)
--   submission_checklists          the checklist copy sent with a submission (1:1)
--   submission_checklist_items     its items
--   submission_checklist_links     one row per link group on an item; its id is
--                                  the stable link-group key
--   submission_checklist_link_members  the attachment / email rows of a group
--
--   Every copy table carries submission_id; composite foreign keys keep it
--   equal to the parent's. Copy rows are never updated or deleted by a client
--   (no UPDATE/DELETE grant); they go with the submission by ON DELETE CASCADE.
--
--   Functions: _checklist_seed_items_valid (catalogue CHECK),
--   can_edit_checklist_templates (RLS helper), _seed_org_checklist_templates,
--   _seed_checklists_on_plan_write (AFTER trigger on organization_plans).
--
--   Feature key transaction_checklists: default 'false', min_tier 'team',
--   is_built false; plan rows false for individual and team, true for
--   enterprise and keepr-internal.
--
--   submission_attachments.local_attachment_id: nullable, not unique, no index.
--
-- Starter content slot (EMPTY in this file)
-- ---------------------------------------------------------------------------
--   checklist_seed_templates ships with no rows. The Residential, Commercial
--   and Land lists arrive in a later data-only migration named
--   <stamp>_backlog_<n>_checklist_starter_content.sql, shaped like this:
--
--   INSERT INTO public.checklist_seed_templates (seed_key, name, description, sort_order, items) VALUES
--     ('residential', 'Residential purchase', '<description>', 10,
--      '[{"title": "<item>", "description": null, "is_required": true, "expected_document_type": "contract"}]'::jsonb),
--     ('commercial', ...), ('land', ...)
--   ON CONFLICT (seed_key) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description,
--     sort_order = EXCLUDED.sort_order, items = EXCLUDED.items, updated_at = now();
--
--   SELECT public._seed_org_checklist_templates(op.organization_id)
--   FROM public.organization_plans op
--   JOIN public.plans p ON p.id = op.plan_id
--   JOIN public.organizations o ON o.id = op.organization_id
--   WHERE public.tier_rank(p.tier) >= public.tier_rank('team') AND o.personal_owner_user_id IS NULL;
--
--   Element shape: {title: text 1..300 (required), description: text <= 2000 | null,
--   is_required: boolean | null (null = false), expected_document_type: one of
--   the 10 document types | null}. No other keys. The items CHECK refuses any
--   other shape, so a malformed list fails the content migration itself.
--
-- Seeding
-- ---------------------------------------------------------------------------
--   An organization gets copies of every catalogue row when its plan row is
--   written with a plan whose tier ranks team or above (AFTER INSERT OR UPDATE
--   OF plan_id on organization_plans). The tier test is the trigger
--   function's first statement. A copy is keyed by (organization_id, seed_key)
--   and is never updated or re-created by a later run.
--
-- Re-runnable: IF NOT EXISTS / CREATE OR REPLACE / DROP POLICY IF EXISTS +
-- CREATE POLICY / ON CONFLICT DO NOTHING; REVOKE and GRANT are idempotent.
-- No BEGIN/COMMIT: the caller supplies the transaction.
-- ============================================================================

-- ---------------------------------------------------------------------------
-- 1. Catalogue validator (created before the table whose CHECK calls it).
--    Returns strictly true or false.
-- ---------------------------------------------------------------------------
CREATE OR REPLACE FUNCTION public._checklist_seed_items_valid(p_items jsonb)
RETURNS boolean
LANGUAGE sql
IMMUTABLE
SET search_path = public
AS $$
  SELECT CASE
    WHEN p_items IS NULL OR jsonb_typeof(p_items) <> 'array' THEN false
    ELSE NOT EXISTS (
      SELECT 1
        FROM jsonb_array_elements(p_items) AS e(elem)
       WHERE NOT (
         CASE
           WHEN jsonb_typeof(e.elem) <> 'object' THEN false
           WHEN EXISTS (
             SELECT 1
               FROM jsonb_object_keys(e.elem) AS k(key)
              WHERE k.key NOT IN ('title', 'description', 'is_required', 'expected_document_type')
           ) THEN false
           WHEN jsonb_typeof(e.elem -> 'title') IS DISTINCT FROM 'string' THEN false
           WHEN char_length(btrim(e.elem ->> 'title')) NOT BETWEEN 1 AND 300 THEN false
           WHEN jsonb_typeof(e.elem -> 'description') NOT IN ('null', 'string') THEN false
           WHEN char_length(e.elem ->> 'description') > 2000 THEN false
           WHEN jsonb_typeof(e.elem -> 'is_required') NOT IN ('null', 'boolean') THEN false
           WHEN jsonb_typeof(e.elem -> 'expected_document_type') NOT IN ('null', 'string') THEN false
           WHEN (e.elem ->> 'expected_document_type') NOT IN
                ('offer', 'inspection', 'disclosure', 'contract', 'appraisal',
                 'amendment', 'addendum', 'title', 'closing', 'other') THEN false
           ELSE true
         END
       )
    )
  END;
$$;

REVOKE EXECUTE ON FUNCTION public._checklist_seed_items_valid(jsonb) FROM PUBLIC, anon, authenticated;

-- ---------------------------------------------------------------------------
-- 2. Tables
-- ---------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS public.checklist_seed_templates (
  seed_key    text        NOT NULL,
  name        text        NOT NULL,
  description text        NULL,
  sort_order  integer     NOT NULL DEFAULT 0,
  items       jsonb       NOT NULL DEFAULT '[]'::jsonb,
  updated_at  timestamptz NOT NULL DEFAULT now(),
  CONSTRAINT checklist_seed_templates_pkey PRIMARY KEY (seed_key),
  CONSTRAINT checklist_seed_templates_seed_key_check CHECK (seed_key ~ '^[a-z][a-z0-9_]*$'),
  CONSTRAINT checklist_seed_templates_name_check CHECK (char_length(btrim(name)) BETWEEN 1 AND 200),
  CONSTRAINT checklist_seed_templates_description_check CHECK (description IS NULL OR char_length(description) <= 2000),
  CONSTRAINT checklist_seed_templates_items_check CHECK (public._checklist_seed_items_valid(items))
);

CREATE TABLE public.checklist_templates (
  id              uuid        NOT NULL DEFAULT gen_random_uuid(),
  organization_id uuid        NOT NULL,
  name            text        NOT NULL,
  description     text        NULL,
  sort_order      integer     NOT NULL DEFAULT 0,
  archived_at     timestamptz NULL,
  seed_key        text        NULL,
  seeded_at       timestamptz NULL,
  created_by      uuid        NULL DEFAULT auth.uid(),
  created_at      timestamptz NOT NULL DEFAULT now(),
  updated_at      timestamptz NOT NULL DEFAULT now(),
  CONSTRAINT checklist_templates_pkey PRIMARY KEY (id),
  CONSTRAINT checklist_templates_organization_id_fkey FOREIGN KEY (organization_id)
    REFERENCES public.organizations(id) ON DELETE CASCADE,
  CONSTRAINT checklist_templates_created_by_fkey FOREIGN KEY (created_by)
    REFERENCES auth.users(id) ON DELETE SET NULL,
  CONSTRAINT checklist_templates_name_check CHECK (char_length(btrim(name)) BETWEEN 1 AND 200),
  CONSTRAINT checklist_templates_description_check CHECK (description IS NULL OR char_length(description) <= 2000),
  CONSTRAINT checklist_templates_seed_pair_check CHECK ((seed_key IS NULL) = (seeded_at IS NULL))
);

CREATE INDEX IF NOT EXISTS checklist_templates_org_sort_idx
  ON public.checklist_templates (organization_id, sort_order);
CREATE UNIQUE INDEX IF NOT EXISTS checklist_templates_org_seed_key_key
  ON public.checklist_templates (organization_id, seed_key)
  WHERE seed_key IS NOT NULL;

CREATE TABLE IF NOT EXISTS public.checklist_template_items (
  id                     uuid        NOT NULL DEFAULT gen_random_uuid(),
  template_id            uuid        NOT NULL,
  title                  text        NOT NULL,
  description            text        NULL,
  is_required            boolean     NOT NULL DEFAULT false,
  expected_document_type text        NULL,
  sort_order             integer     NOT NULL DEFAULT 0,
  created_at             timestamptz NOT NULL DEFAULT now(),
  updated_at             timestamptz NOT NULL DEFAULT now(),
  CONSTRAINT checklist_template_items_pkey PRIMARY KEY (id),
  CONSTRAINT checklist_template_items_template_id_fkey FOREIGN KEY (template_id)
    REFERENCES public.checklist_templates(id) ON DELETE CASCADE,
  CONSTRAINT checklist_template_items_title_check CHECK (char_length(btrim(title)) BETWEEN 1 AND 300),
  CONSTRAINT checklist_template_items_description_check CHECK (description IS NULL OR char_length(description) <= 2000),
  CONSTRAINT checklist_template_items_expected_document_type_check CHECK (
    expected_document_type IS NULL OR expected_document_type IN
      ('offer', 'inspection', 'disclosure', 'contract', 'appraisal',
       'amendment', 'addendum', 'title', 'closing', 'other')
  )
);

CREATE INDEX IF NOT EXISTS checklist_template_items_template_sort_idx
  ON public.checklist_template_items (template_id, sort_order);

CREATE TABLE IF NOT EXISTS public.submission_checklists (
  id            uuid        NOT NULL DEFAULT gen_random_uuid(),
  submission_id uuid        NOT NULL,
  template_name text        NOT NULL,
  created_at    timestamptz NOT NULL DEFAULT now(),
  CONSTRAINT submission_checklists_pkey PRIMARY KEY (id),
  CONSTRAINT submission_checklists_submission_id_fkey FOREIGN KEY (submission_id)
    REFERENCES public.transaction_submissions(id) ON DELETE CASCADE,
  CONSTRAINT submission_checklists_submission_id_key UNIQUE (submission_id),
  CONSTRAINT submission_checklists_id_submission_id_key UNIQUE (id, submission_id)
);

CREATE TABLE IF NOT EXISTS public.submission_checklist_items (
  id                      uuid        NOT NULL DEFAULT gen_random_uuid(),
  submission_id           uuid        NOT NULL,
  submission_checklist_id uuid        NOT NULL,
  title                   text        NOT NULL,
  is_required             boolean     NOT NULL,
  is_checked              boolean     NOT NULL DEFAULT false,
  note                    text        NULL,
  sort_order              integer     NOT NULL DEFAULT 0,
  created_at              timestamptz NOT NULL DEFAULT now(),
  CONSTRAINT submission_checklist_items_pkey PRIMARY KEY (id),
  CONSTRAINT submission_checklist_items_checklist_fkey FOREIGN KEY (submission_checklist_id, submission_id)
    REFERENCES public.submission_checklists(id, submission_id) ON DELETE CASCADE,
  CONSTRAINT submission_checklist_items_id_submission_id_key UNIQUE (id, submission_id)
);

CREATE INDEX IF NOT EXISTS submission_checklist_items_checklist_idx
  ON public.submission_checklist_items (submission_checklist_id);

CREATE TABLE IF NOT EXISTS public.submission_checklist_links (
  id                           uuid        NOT NULL DEFAULT gen_random_uuid(),
  submission_id                uuid        NOT NULL,
  submission_checklist_item_id uuid        NOT NULL,
  kind                         text        NOT NULL,
  label                        text        NOT NULL,
  sort_order                   integer     NOT NULL DEFAULT 0,
  created_at                   timestamptz NOT NULL DEFAULT now(),
  CONSTRAINT submission_checklist_links_pkey PRIMARY KEY (id),
  CONSTRAINT submission_checklist_links_item_fkey FOREIGN KEY (submission_checklist_item_id, submission_id)
    REFERENCES public.submission_checklist_items(id, submission_id) ON DELETE CASCADE,
  CONSTRAINT submission_checklist_links_kind_check CHECK (kind IN ('attachment', 'email')),
  CONSTRAINT submission_checklist_links_id_submission_id_kind_key UNIQUE (id, submission_id, kind)
);

CREATE INDEX IF NOT EXISTS submission_checklist_links_item_idx
  ON public.submission_checklist_links (submission_checklist_item_id);

CREATE TABLE IF NOT EXISTS public.submission_checklist_link_members (
  id                       uuid NOT NULL DEFAULT gen_random_uuid(),
  submission_id            uuid NOT NULL,
  link_id                  uuid NOT NULL,
  kind                     text NOT NULL,
  submission_attachment_id uuid NULL,
  submission_message_id    uuid NULL,
  CONSTRAINT submission_checklist_link_members_pkey PRIMARY KEY (id),
  CONSTRAINT submission_checklist_link_members_link_fkey FOREIGN KEY (link_id, submission_id, kind)
    REFERENCES public.submission_checklist_links(id, submission_id, kind) ON DELETE CASCADE,
  CONSTRAINT submission_checklist_link_members_attachment_fkey FOREIGN KEY (submission_attachment_id)
    REFERENCES public.submission_attachments(id) ON DELETE CASCADE,
  CONSTRAINT submission_checklist_link_members_message_fkey FOREIGN KEY (submission_message_id)
    REFERENCES public.submission_messages(id) ON DELETE CASCADE,
  CONSTRAINT submission_checklist_link_members_target_check CHECK (
    (kind = 'attachment' AND submission_attachment_id IS NOT NULL AND submission_message_id IS NULL)
    OR (kind = 'email' AND submission_message_id IS NOT NULL AND submission_attachment_id IS NULL)
  ),
  CONSTRAINT submission_checklist_link_members_link_attachment_key UNIQUE (link_id, submission_attachment_id),
  CONSTRAINT submission_checklist_link_members_link_message_key UNIQUE (link_id, submission_message_id)
);

CREATE INDEX IF NOT EXISTS submission_checklist_link_members_link_idx
  ON public.submission_checklist_link_members (link_id);
CREATE INDEX IF NOT EXISTS submission_checklist_link_members_attachment_idx
  ON public.submission_checklist_link_members (submission_attachment_id);
CREATE INDEX IF NOT EXISTS submission_checklist_link_members_message_idx
  ON public.submission_checklist_link_members (submission_message_id);

CREATE OR REPLACE TRIGGER checklist_templates_updated_at
  BEFORE UPDATE ON public.checklist_templates
  FOR EACH ROW EXECUTE FUNCTION public.update_updated_at_column();

CREATE OR REPLACE TRIGGER checklist_template_items_updated_at
  BEFORE UPDATE ON public.checklist_template_items
  FOR EACH ROW EXECUTE FUNCTION public.update_updated_at_column();

-- ---------------------------------------------------------------------------
-- 3. Who may edit an organization's templates: an editor role on THAT
--    organization's membership row, and the organization holds the feature.
-- ---------------------------------------------------------------------------
CREATE OR REPLACE FUNCTION public.can_edit_checklist_templates(p_org_id uuid)
RETURNS boolean
LANGUAGE sql
STABLE
SECURITY DEFINER
SET search_path = public
AS $$
  SELECT EXISTS (
           SELECT 1
             FROM public.organization_members m
            WHERE m.organization_id = p_org_id
              AND m.user_id = (SELECT auth.uid())
              AND m.role IN ('broker', 'admin', 'it_admin')
         )
     AND COALESCE((public.check_feature_access(p_org_id, 'transaction_checklists') ->> 'allowed')::boolean, false);
$$;

REVOKE EXECUTE ON FUNCTION public.can_edit_checklist_templates(uuid) FROM PUBLIC, anon;
GRANT EXECUTE ON FUNCTION public.can_edit_checklist_templates(uuid) TO authenticated;

-- ---------------------------------------------------------------------------
-- 4. Seeding: copy every catalogue row an organization does not yet hold.
--    Returns the number of templates inserted.
-- ---------------------------------------------------------------------------
CREATE OR REPLACE FUNCTION public._seed_org_checklist_templates(p_org_id uuid)
RETURNS integer
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
  v_count integer;
BEGIN
  IF p_org_id IS NULL OR NOT EXISTS (SELECT 1 FROM public.organizations WHERE id = p_org_id) THEN
    RETURN 0;
  END IF;

  WITH inserted AS (
    INSERT INTO public.checklist_templates
      (organization_id, name, description, sort_order, seed_key, seeded_at, created_by)
    SELECT p_org_id, s.name, s.description, s.sort_order, s.seed_key, now(), NULL
      FROM public.checklist_seed_templates s
    ON CONFLICT (organization_id, seed_key) WHERE seed_key IS NOT NULL DO NOTHING
    RETURNING id, seed_key
  ), inserted_items AS (
    INSERT INTO public.checklist_template_items
      (template_id, title, description, is_required, expected_document_type, sort_order)
    SELECT i.id,
           e.elem ->> 'title',
           e.elem ->> 'description',
           COALESCE((e.elem ->> 'is_required')::boolean, false),
           e.elem ->> 'expected_document_type',
           (e.ord * 10)::integer
      FROM inserted i
      JOIN public.checklist_seed_templates s ON s.seed_key = i.seed_key
      CROSS JOIN LATERAL jsonb_array_elements(s.items) WITH ORDINALITY AS e(elem, ord)
    RETURNING 1
  )
  SELECT count(*)::integer INTO v_count FROM inserted;

  RETURN v_count;
END
$$;

REVOKE EXECUTE ON FUNCTION public._seed_org_checklist_templates(uuid) FROM PUBLIC, anon, authenticated;

CREATE OR REPLACE FUNCTION public._seed_checklists_on_plan_write()
RETURNS trigger
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
BEGIN
  IF public.tier_rank((SELECT p.tier FROM public.plans p WHERE p.id = NEW.plan_id))
     < public.tier_rank('team') THEN
    RETURN NULL;
  END IF;
  PERFORM public._seed_org_checklist_templates(NEW.organization_id);
  RETURN NULL;
END
$$;

REVOKE EXECUTE ON FUNCTION public._seed_checklists_on_plan_write() FROM PUBLIC, anon, authenticated;

CREATE OR REPLACE TRIGGER seed_checklists_on_plan_write
  AFTER INSERT OR UPDATE OF plan_id ON public.organization_plans
  FOR EACH ROW
  EXECUTE FUNCTION public._seed_checklists_on_plan_write();

-- ---------------------------------------------------------------------------
-- 5. Row-level security and grants
-- ---------------------------------------------------------------------------
ALTER TABLE public.checklist_seed_templates          ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.checklist_templates               ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.checklist_template_items          ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.submission_checklists             ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.submission_checklist_items        ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.submission_checklist_links        ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.submission_checklist_link_members ENABLE ROW LEVEL SECURITY;

-- Catalogue: no policies, no client grants.
REVOKE ALL ON public.checklist_seed_templates FROM anon, authenticated;

-- 5a. checklist_templates -- read by any member; written by an editor; never deleted.
REVOKE ALL ON public.checklist_templates FROM anon, authenticated;
GRANT SELECT ON public.checklist_templates TO authenticated;
GRANT INSERT (organization_id, name, description, sort_order, archived_at) ON public.checklist_templates TO authenticated;
GRANT UPDATE (name, description, sort_order, archived_at) ON public.checklist_templates TO authenticated;

DROP POLICY IF EXISTS checklist_templates_select_member ON public.checklist_templates;
CREATE POLICY checklist_templates_select_member ON public.checklist_templates
  FOR SELECT TO authenticated
  USING (checklist_templates.organization_id IN (SELECT public.get_user_org_ids((SELECT auth.uid()))));

DROP POLICY IF EXISTS checklist_templates_insert_editor ON public.checklist_templates;
CREATE POLICY checklist_templates_insert_editor ON public.checklist_templates
  FOR INSERT TO authenticated
  WITH CHECK (public.can_edit_checklist_templates(checklist_templates.organization_id));

DROP POLICY IF EXISTS checklist_templates_update_editor ON public.checklist_templates;
CREATE POLICY checklist_templates_update_editor ON public.checklist_templates
  FOR UPDATE TO authenticated
  USING (public.can_edit_checklist_templates(checklist_templates.organization_id))
  WITH CHECK (public.can_edit_checklist_templates(checklist_templates.organization_id));

-- 5b. checklist_template_items -- read by any member; written and deleted by an editor.
REVOKE ALL ON public.checklist_template_items FROM anon, authenticated;
GRANT SELECT, DELETE ON public.checklist_template_items TO authenticated;
GRANT INSERT (template_id, title, description, is_required, expected_document_type, sort_order)
  ON public.checklist_template_items TO authenticated;
GRANT UPDATE (title, description, is_required, expected_document_type, sort_order)
  ON public.checklist_template_items TO authenticated;

DROP POLICY IF EXISTS checklist_template_items_select_member ON public.checklist_template_items;
CREATE POLICY checklist_template_items_select_member ON public.checklist_template_items
  FOR SELECT TO authenticated
  USING (EXISTS (
    SELECT 1
      FROM public.checklist_templates t
     WHERE t.id = checklist_template_items.template_id
       AND t.organization_id IN (SELECT public.get_user_org_ids((SELECT auth.uid())))
  ));

DROP POLICY IF EXISTS checklist_template_items_insert_editor ON public.checklist_template_items;
CREATE POLICY checklist_template_items_insert_editor ON public.checklist_template_items
  FOR INSERT TO authenticated
  WITH CHECK (EXISTS (
    SELECT 1
      FROM public.checklist_templates t
     WHERE t.id = checklist_template_items.template_id
       AND public.can_edit_checklist_templates(t.organization_id)
  ));

DROP POLICY IF EXISTS checklist_template_items_update_editor ON public.checklist_template_items;
CREATE POLICY checklist_template_items_update_editor ON public.checklist_template_items
  FOR UPDATE TO authenticated
  USING (EXISTS (
    SELECT 1
      FROM public.checklist_templates t
     WHERE t.id = checklist_template_items.template_id
       AND public.can_edit_checklist_templates(t.organization_id)
  ))
  WITH CHECK (EXISTS (
    SELECT 1
      FROM public.checklist_templates t
     WHERE t.id = checklist_template_items.template_id
       AND public.can_edit_checklist_templates(t.organization_id)
  ));

DROP POLICY IF EXISTS checklist_template_items_delete_editor ON public.checklist_template_items;
CREATE POLICY checklist_template_items_delete_editor ON public.checklist_template_items
  FOR DELETE TO authenticated
  USING (EXISTS (
    SELECT 1
      FROM public.checklist_templates t
     WHERE t.id = checklist_template_items.template_id
       AND public.can_edit_checklist_templates(t.organization_id)
  ));

-- 5c. The submitted copy -- read by the submitter and the organization's
--     brokers and admins (the same readers as submission_attachments);
--     inserted only by the submitter while the submission is 'uploading';
--     never updated or deleted by a client.
REVOKE ALL ON public.submission_checklists             FROM anon, authenticated;
REVOKE ALL ON public.submission_checklist_items        FROM anon, authenticated;
REVOKE ALL ON public.submission_checklist_links        FROM anon, authenticated;
REVOKE ALL ON public.submission_checklist_link_members FROM anon, authenticated;
GRANT SELECT, INSERT ON public.submission_checklists             TO authenticated;
GRANT SELECT, INSERT ON public.submission_checklist_items        TO authenticated;
GRANT SELECT, INSERT ON public.submission_checklist_links        TO authenticated;
GRANT SELECT, INSERT ON public.submission_checklist_link_members TO authenticated;

DROP POLICY IF EXISTS submission_checklists_select ON public.submission_checklists;
CREATE POLICY submission_checklists_select ON public.submission_checklists
  FOR SELECT TO authenticated
  USING (EXISTS (
    SELECT 1
      FROM public.transaction_submissions ts
     WHERE ts.id = submission_checklists.submission_id
       AND (ts.submitted_by = (SELECT auth.uid())
            OR EXISTS (
              SELECT 1
                FROM public.organization_members om
               WHERE om.organization_id = ts.organization_id
                 AND om.user_id = (SELECT auth.uid())
                 AND om.role IN ('broker', 'admin')
            ))
  ));

DROP POLICY IF EXISTS submission_checklists_insert ON public.submission_checklists;
CREATE POLICY submission_checklists_insert ON public.submission_checklists
  FOR INSERT TO authenticated
  WITH CHECK (EXISTS (
    SELECT 1
      FROM public.transaction_submissions ts
     WHERE ts.id = submission_checklists.submission_id
       AND ts.submitted_by = (SELECT auth.uid())
       AND ts.status = 'uploading'
       AND COALESCE((public.check_feature_access(ts.organization_id, 'transaction_checklists') ->> 'allowed')::boolean, false)
  ));

DROP POLICY IF EXISTS submission_checklist_items_select ON public.submission_checklist_items;
CREATE POLICY submission_checklist_items_select ON public.submission_checklist_items
  FOR SELECT TO authenticated
  USING (EXISTS (
    SELECT 1
      FROM public.transaction_submissions ts
     WHERE ts.id = submission_checklist_items.submission_id
       AND (ts.submitted_by = (SELECT auth.uid())
            OR EXISTS (
              SELECT 1
                FROM public.organization_members om
               WHERE om.organization_id = ts.organization_id
                 AND om.user_id = (SELECT auth.uid())
                 AND om.role IN ('broker', 'admin')
            ))
  ));

DROP POLICY IF EXISTS submission_checklist_items_insert ON public.submission_checklist_items;
CREATE POLICY submission_checklist_items_insert ON public.submission_checklist_items
  FOR INSERT TO authenticated
  WITH CHECK (EXISTS (
    SELECT 1
      FROM public.transaction_submissions ts
     WHERE ts.id = submission_checklist_items.submission_id
       AND ts.submitted_by = (SELECT auth.uid())
       AND ts.status = 'uploading'
  ));

DROP POLICY IF EXISTS submission_checklist_links_select ON public.submission_checklist_links;
CREATE POLICY submission_checklist_links_select ON public.submission_checklist_links
  FOR SELECT TO authenticated
  USING (EXISTS (
    SELECT 1
      FROM public.transaction_submissions ts
     WHERE ts.id = submission_checklist_links.submission_id
       AND (ts.submitted_by = (SELECT auth.uid())
            OR EXISTS (
              SELECT 1
                FROM public.organization_members om
               WHERE om.organization_id = ts.organization_id
                 AND om.user_id = (SELECT auth.uid())
                 AND om.role IN ('broker', 'admin')
            ))
  ));

DROP POLICY IF EXISTS submission_checklist_links_insert ON public.submission_checklist_links;
CREATE POLICY submission_checklist_links_insert ON public.submission_checklist_links
  FOR INSERT TO authenticated
  WITH CHECK (EXISTS (
    SELECT 1
      FROM public.transaction_submissions ts
     WHERE ts.id = submission_checklist_links.submission_id
