DROP POLICY IF EXISTS submission_checklist_link_members_select ON public.submission_checklist_link_members;
CREATE POLICY submission_checklist_link_members_select ON public.submission_checklist_link_members
  FOR SELECT TO authenticated
  USING (EXISTS (
    SELECT 1
      FROM public.transaction_submissions ts
     WHERE ts.id = submission_checklist_link_members.submission_id
       AND (ts.submitted_by = (SELECT auth.uid())
            OR EXISTS (
              SELECT 1
                FROM public.organization_members om
               WHERE om.organization_id = ts.organization_id
                 AND om.user_id = (SELECT auth.uid())
                 AND om.role IN ('broker', 'admin')
            ))
  ));

DROP POLICY IF EXISTS submission_checklist_link_members_insert ON public.submission_checklist_link_members;
CREATE POLICY submission_checklist_link_members_insert ON public.submission_checklist_link_members
  FOR INSERT TO authenticated
  WITH CHECK (
    EXISTS (
      SELECT 1
        FROM public.transaction_submissions ts
       WHERE ts.id = submission_checklist_link_members.submission_id
         AND ts.submitted_by = (SELECT auth.uid())
         AND ts.status = 'uploading'
    )
    AND (submission_checklist_link_members.submission_attachment_id IS NULL
         OR EXISTS (
           SELECT 1
             FROM public.submission_attachments a
            WHERE a.id = submission_checklist_link_members.submission_attachment_id
              AND a.submission_id = submission_checklist_link_members.submission_id
         ))
    AND (submission_checklist_link_members.submission_message_id IS NULL
         OR EXISTS (
           SELECT 1
             FROM public.submission_messages m
            WHERE m.id = submission_checklist_link_members.submission_message_id
              AND m.submission_id = submission_checklist_link_members.submission_id
              AND m.channel = 'email'
         ))
  );

-- ---------------------------------------------------------------------------
-- 6. Feature key
-- ---------------------------------------------------------------------------
INSERT INTO public.feature_definitions
  (key, name, description, category, value_type, default_value, min_tier, sort_order, is_built)
VALUES (
  'transaction_checklists',
  'Transaction checklists',
  'Checklist templates a brokerage edits in the broker portal, applied to a transaction on the desktop and sent with its submission (BACKLOG-3473).',
  'access',
  'boolean',
  'false',
  'team',
  135,
  false
)
ON CONFLICT (key) DO NOTHING;

INSERT INTO public.plan_features (plan_id, feature_id, enabled, value)
SELECT p.id, fd.id, v.enabled, v.enabled::text
FROM (VALUES
  ('individual',     false),
  ('team',           false),
  ('enterprise',     true),
  ('keepr-internal', true)
) AS v(slug, enabled)
JOIN public.plans p ON p.slug = v.slug
JOIN public.feature_definitions fd ON fd.key = 'transaction_checklists'
ON CONFLICT (plan_id, feature_id) DO NOTHING;

-- ---------------------------------------------------------------------------
-- 7. The local attachment id, so the submitted copy can map desktop
--    attachment ids onto submission_attachments rows.
-- ---------------------------------------------------------------------------
ALTER TABLE public.submission_attachments ADD COLUMN IF NOT EXISTS local_attachment_id text;

COMMENT ON COLUMN public.submission_attachments.local_attachment_id IS
  'BACKLOG-3473: the desktop attachments.id this row was uploaded from. Nullable, not unique.';
